WITH sales_agg AS ( SELECT ss.ss_store_sk, i.i_category, d.d_year, d.d_month_seq, SUM(ss.ss_net_paid_inc_tax) AS total_sales, SUM(ss.ss_ext_discount_amt) AS total_discount, SUM(ss.ss_net_profit) AS total_profit, COUNT(*) AS sales_transactions FROM store_sales ss JOIN date_dim d ON ss.ss_sold_date_sk = d.d_date_sk JOIN item i ON ss.ss_item_sk = i.i_item_sk GROUP BY ss.ss_store_sk, i.i_category, d.d_year, d.d_month_seq ), returns_agg AS ( SELECT i.i_category, d.d_year, d.d_month_seq, SUM(cr.cr_return_amount) AS total_return_amount, SUM(cr.cr_return_quantity) AS total_return_qty, SUM(cr.cr_net_loss) AS total_net_loss FROM catalog_returns cr JOIN date_dim d ON cr.cr_returned_date_sk = d.d_date_sk JOIN item i ON cr.cr_item_sk = i.i_item_sk GROUP BY i.i_category, d.d_year, d.d_month_seq ), combined AS ( SELECT s.ss_store_sk, s.i_category, s.d_year, s.d_month_seq, s.total_sales, s.total_discount, s.total_profit, s.sales_transactions, COALESCE(r.total_return_amount, 0) AS total_return_amount, COALESCE(r.total_return_qty, 0) AS total_return_qty, COALESCE(r.total_net_loss, 0) AS total_net_loss, CASE WHEN s.total_sales > 0 THEN COALESCE(r.total_return_amount, 0) / s.total_sales ELSE 0 END AS return_rate, (s.total_profit - COALESCE(r.total_net_loss, 0)) AS net_profit_after_returns FROM sales_agg s LEFT JOIN returns_agg r ON s.i_category = r.i_category AND s.d_year = r.d_year AND s.d_month_seq = r.d_month_seq ), ranked AS ( SELECT c.ss_store_sk, st.s_store_name, c.i_category, c.d_year, c.d_month_seq, c.total_sales, c.total_discount, c.total_profit, c.total_return_amount, c.total_return_qty, c.return_rate, c.net_profit_after_returns, ROW_NUMBER() OVER (PARTITION BY c.d_year, c.d_month_seq, c.i_category ORDER BY c.net_profit_after_returns DESC) AS store_rank FROM combined c JOIN store st ON c.ss_store_sk = st.s_store_sk WHERE c.net_profit_after_returns > 0 ) SELECT ss_store_sk, s_store_name, i_category, d_year, d_month_seq, total_sales, total_discount, total_profit, total_return_amount, total_return_qty, return_rate, net_profit_after_returns, store_rank FROM ranked WHERE store_rank <= 3 ORDER BY d_year, d_month_seq, i_category, store_rank
